let id = Math.floor(Math.random() * 30001)
let timestamp = Math.floor(msg.payload/1000)
msg.payload = JSON.stringify({id: id, timestamp: timestamp})
return msg;

let N = msg.payload.id % 7711;
let csv_data = flow.get("csv_data") || [];
if (csv_data.length === 0 || N === 0) return;
msg.subId = msg.payload.id;
msg.payload = csv_data[N];
return msg;

// 1. Get the current counter value, default to 0.
let rowNum = context.get("idLogCsvRowCounter") || 0;
rowNum++;
context.set("idLogCsvRowCounter", rowNum);
let data = JSON.parse(msg.payload);
// Create the CSV string payload according to Slide 13 format.
msg.payload = `${rowNum},${data.id},${data.timestamp}\n`;

return msg;

let infoString = msg.payload.col9; 
let originalPayloadString = msg.payload.col10;
if (typeof originalPayloadString == 'undefined')
    originalPayloadString = "{}";

// --- Extract all topics using Regular Expressions ---
const regex = /Publish Message \[([^\]]+)\]/g; // Regex to find "[topic]" after "Publish Message "
let topics = [];
let match;

// Loop through all matches found in the infoString
while ((match = regex.exec(infoString)) !== null) {
    // match[1] contains the captured group (the topic itself)
    if (match[1]) {
        topics.push(match[1].trim()); // Add the extracted topic to the array, removing whitespace
    }
}

// --- Parse the multi-payload string into an array of objects ---
let payloadObjects = [];
// 1. Clean up common issues: Replace double quotes used for escaping within the string
let cleanedPayloadString = originalPayloadString.replace(/""/g, '"');

// 2. Wrap with brackets to make it look like a JSON array
let arrayLikeString = '[' + cleanedPayloadString + ']';

// 3. Parse the string into an array of objects
payloadObjects = JSON.parse(arrayLikeString);


for (let i = 0; i < topics.length; i++) {
msg.payload = JSON.stringify({
    timestamp: (Math.floor(Date.now() / 1000)).toString(), 
    id: msg.subId.toString(), // The ID from the subscribed message
    topic: topics[i],
    payload: payloadObjects[i] || "{}" // The original payload string from CSV
});
msg.topic = topics[i]; // Set the topic for the MQTT out node
node.send(msg)
}

return null;

let ackCount = context.get("globalAckCounter") || 0;
ackCount++;
context.set("globalAckCounter", ackCount);

// Add the current count to the message for the ThingSpeak node
msg.currentAckCount = ackCount;
let timestamp = Math.floor(Date.now() / 1000);
let subId = msg.subId; // Make sure this exists in the incoming msg!
let msgType = msg.payload.col9; // Get the ACK type string
let ackIndex = msgType.indexOf("Ack");
msgType = msgType.substring(0, ackIndex + 3).trim();
// Get and increment the row number specific to ack_log.csv (using node context)
let ackLogRowNum = context.get("ackLogCsvRowCounter") || 0;
ackLogRowNum++;
context.set("ackLogCsvRowCounter", ackLogRowNum);
let csvString = `${ackLogRowNum},${timestamp},${subId},${msgType}\n`;
msg.payload = csvString;
return msg;

// Initialize log files on Node-RED start/deploy
const fs = global.get('fs');

// --- Define log files and their headers ---
const filesToInitialize = [
    { path: 'C:/Users/Karim Negm/Documents/IoT/Challenge 3/id_log.csv', header: "No.,ID,TIMESTAMP\n" },
    { path: 'C:/Users/Karim Negm/Documents/IoT/Challenge 3/ack_log.csv', header: "No.,TIMESTAMP,SUB_ID,MSG_TYPE\n" },
    { path: 'C:/Users/Karim Negm/Documents/IoT/Challenge 3/filtered_pubs.csv', header: "No.,LONG,LAT,MEAN_VALUE,TYPE,UNIT,DESCRIPTION\n" }
];

if (!fs) {
    node.error("Node.js 'fs' module not loaded. Check settings.js and restart Node-RED.");
    return null; // Stop if fs isn't available
}

// Loop through each file definition
filesToInitialize.forEach(fileInfo => {
    try {
        // Overwrite or create the file with its specific header
        fs.writeFileSync(fileInfo.path, fileInfo.header);
        node.log(`Initialized: ${fileInfo.path}`); // Log success for each file
    } catch (err) {
        // Log error if writing fails for a specific file
        node.error(`Failed to initialize ${fileInfo.path}: ${err.message}`);
    }
});

// No message should be passed on from this initialization node
return null;

// --- Function: Limit to 80 Messages ---
let msgCount = context.get("receivedMsgCount") || 0;
msgCount++;
context.set("receivedMsgCount", msgCount);

if (msgCount <= 80) {
    node.status({ fill: "green", shape: "dot", text: "Processing #" + msgCount });
    // Pass the message on for processing
    return msg;
} else {
    node.status({ fill: "red", shape: "ring", text: "Stopped after 80" });
    // Stop the flow for this message and subsequent ones
    return null;
}

let incomingData;
// Parse the incoming JSON string payload
try {
    incomingData = JSON.parse(msg.payload);
} catch (e) {
    // If parsing fails, we can't process it. Silently ignore or log.
    node.error("Failed to parse incoming payload string: " + e.message, msg);
    return null; // Stop if input is not valid JSON
}

let payload = incomingData.payload; // This is the object parsed from CSV col10

// Check for Temp in F
if (payload && payload.type === "temperature" && payload.unit === "F") {

    // Validate range before calculating mean
    if (Array.isArray(payload.range) && payload.range.length === 2 &&
        typeof payload.range[0] === 'number' && typeof payload.range[1] === 'number') {

        let meanValue = (payload.range[0] + payload.range[1]) / 2;
        let filteredRowNum = context.get("filteredPubsRowCounter") || 0;
        // Reset chart on first publish
        if (filteredRowNum === 0) node.send([{ payload: [] }, null]);
        // --- Output 1: Send mean value for Chart ---
        node.send([{ payload: meanValue }, null]); // Send to output 1

        // --- Output 2: Send CSV string for Log ---
        // Get row counter for filtered_pubs.csv, default to 0
        filteredRowNum++; // Increment row number
        context.set("filteredPubsRowCounter", filteredRowNum); // Save updated counter

        // Format CSV line (using defaults || '' if fields might be missing)
        let description = payload.description || "";
        // Ensure quotes in description are escaped for CSV standard (replace " with "")
        let cleanDescription = description.replace(/"/g, '""');
        let csvString = `${filteredRowNum},${payload.long || ''},${payload.lat || ''},${meanValue},${payload.type || ''},${payload.unit || ''},"${cleanDescription}"\n`;

        // Send CSV string to output 2
        node.send([null, { payload: csvString }]); // Send to output 2

    } else {
        // Log if range is invalid for a Temp F reading
        node.warn("Invalid 'range' data for Temp F payload");
    }
}

return null;
